/// A slice descriptor with optional start, stop, and step fields.
/// 
/// Invariants:
/// - If `step` is `Some(n)`, then `n > 0`.
/// - If both `start` and `stop` are `Some`, then `start <= stop`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Slice {
    pub start: Option<usize>,
    pub stop: Option<usize>,
    pub step: Option<usize>,
}

/// Constructs a `Slice` descriptor from the given optional `start`, `stop`, and `step` values.
/// 
/// Panics if:
/// - `step` is `Some(0)`.
/// - Both `start` and `stop` are `Some` and `start > stop`.
pub fn s_(start: Option<usize>, stop: Option<usize>, step: Option<usize>) -> Slice {
    if let Some(s) = step {
        assert!(s > 0, "step must be strictly positive");
    }
    if let (Some(s), Some(e)) = (start, stop) {
        assert!(s <= e, "start must be less than or equal to stop");
    }

    Slice {
        start,
        stop,
        step,
    }
}

